        "content": "피나세트정의 주성분은 피나스테리드(Finasteride) 1mg이고, 식약처 허가사항상 만 18~41세 성인 남성의 남성형 탈모증(안드로겐 탈모증) 치료에 쓰는 전문의약품이에요. 익수제약(주)이 만드는 정제이고, 품목번호는 201905545예요. 오리지널인 프로페시아와 같은 성분·함량의 제네릭이라 효과는 동등하게 보면 돼요.\n\n검색으로 들어온 분 대부분은 효과보다 값을 먼저 보고 있을 텐데, 가격을 따지기 전에 이 약이 정확히 어떤 약인지부터 짚을게요. 피나스테리드는 모발용제로 분류된 5α-환원효소 억제 계열 성분이에요. 식약처 허가사항을 보면 일반적으로 3개월 이상 복용해야 치료 효과가 나타나고, 복용을 중단하면 12개월 내에 효과가 사라져요.\n\n그래서 이 약은 한두 통 사고 끝나는 게 아니라 장기로 이어가는 약이라, 한 정 단가가 곧 매달 나가는 비용이 돼요. 같은 1mg이라도 어디서 어떤 제품을 고르느냐로 1년 비용이 꽤 벌어지죠. 단가 환산이 핵심인 이유예요. 값부터 짚을게요.",
