        "content": "피나세트정은 식약처 허가사항상 여성과 소아에게 투여하면 안 돼요. 특히 임부 또는 임신 가능성이 있는 여성은 부서진 정제 조각을 만지기만 해도 피부로 흡수돼 남성 태아 외부 생식기에 이상을 초래할 수 있어요. 코팅이 깨진 조각은 절대 만지면 안 돼요. 접촉을 피하세요.\n\n양성 전립샘비대증 등으로 5mg 피나스테리드나 다른 5α-환원효소 억제제를 이미 복용 중이라면 함께 쓰면 안 돼요. 유당을 함유하고 있어서 갈락토오스 불내성, Lapp 유당분해효소 결핍증, 포도당-갈락토오스 흡수장애가 있는 분도 복용 금지예요. 대두유와 콩·땅콩에 과민증이 있는 경우도 피해야 해요.\n\n간에서 광범위하게 대사되므로 간기능 이상 환자는 신중히 투여해요. PSA 수치가 영향을 받을 수 있으니 전립선암 검진을 앞두고 있다면 피나세트정 복용 사실을 의사에게 알려야 정확히 해석돼요. 처방전이 필요한 전문의약품인 만큼, 시작과 중단·변경은 반드시 의사와 상의하세요."
