          "(주)이든파마가 제조하는 피나스테리드 5mg 전문의약품이고요. 식약처 품목번호 201500591로 허가됐고, 허가 분류는 기타 비뇨생식기관 및 항문용약(분류번호 02590)이에요.\n\n피나스테리드는 5알파환원효소 2형을 억제해서 테스토스테론이 DHT(디하이드로테스토스테론)로 전환되는 경로를 막아요. 전립선 세포 증식에 관여하는 DHT가 줄어들면 비대해진 전립선이 점차 퇴행하고 배뇨 증상이 개선돼요. 탈모 관련 맥락에서 같은 기전이 언급되지만, 피나드정5mg의 허가 목적은 전립선이에요.\n\n전문의약품이라 처방전 없이는 구매할 수 없어요. 처방 전 의사가 감염, 전립선암, 협착 질환 등을 배제하기 위한 적절한 평가를 먼저 실시해야 한다고 식약처 허가사항에 명시돼 있어요.",
