        content:
          "핀스타정의 주요 효과는 양성전립샘비대증 증상 개선, 비후된 전립샘의 퇴행, 요류 개선이에요. 여기에 더해 급성 요폐 발생빈도 감소, 전립샘 경요도 절제술(TURP)을 포함한 수술의 필요성 감소까지 허가된 효과죠. 이 허가 내용은 식약처 허가사항에 명확히 근거를 두고 있어요.\n\n작용 원리는 5α-환원효소 억제예요. 테스토스테론이 전립선 세포를 자극하는 DHT(디하이드로테스토스테론)로 전환되는 과정을 막아, 비대해진 전립선이 시간이 지나면서 줄어들게 해요. 전립선이 방광을 누르는 정도가 줄면 소변 줄기가 세지고 야간뇨·잔뇨감 같은 증상이 개선되죠. DHT 억제 원리는 남성형 탈모 치료에서도 동일하게 쓰이는데, 탈모·모발 목적으로는 이 약이 아닌 1mg 허가 제품이 필요해요.\n\n증상이 개선되더라도 최소 6개월간 치료가 필요하고, 처음 몇 주 안에 극적인 변화가 없어도 복용을 임의로 중단하지 말아야 해요. 경과는 처방 의사와 함께 평가해야 해요. 효과는 더뎌요.",
